// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ReceiveKycWebhook Receive a KYC vendor's result
	// (POST /v1/accounts/kyc/webhooks/{provider})
	ReceiveKycWebhook(ctx context.Context, request ReceiveKycWebhookRequestObject) (ReceiveKycWebhookResponseObject, error)
	// ListMyMemberships List the accounts the caller belongs to
	// (GET /v1/accounts/me/memberships)
	ListMyMemberships(ctx context.Context, request ListMyMembershipsRequestObject) (ListMyMembershipsResponseObject, error)
	// AcceptInvitation Accept an invitation
	// (POST /v1/accounts/me/memberships/{tenantId}/acceptance)
	AcceptInvitation(ctx context.Context, request AcceptInvitationRequestObject) (AcceptInvitationResponseObject, error)
	// ListRoles List the built-in roles and their permissions
	// (GET /v1/accounts/roles)
	ListRoles(ctx context.Context, request ListRolesRequestObject) (ListRolesResponseObject, error)
	// ListKycReviews The staff review queue (staff only)
	// (GET /v1/accounts/staff/kyc-reviews)
	ListKycReviews(ctx context.Context, request ListKycReviewsRequestObject) (ListKycReviewsResponseObject, error)
	// GetKycReview One check under review, with what the reviewer needs (staff only)
	// (GET /v1/accounts/staff/kyc-reviews/{checkId})
	GetKycReview(ctx context.Context, request GetKycReviewRequestObject) (GetKycReviewResponseObject, error)
	// DecideKycReview Pass or fail a check under review (staff only)
	// (POST /v1/accounts/staff/kyc-reviews/{checkId}/decision)
	DecideKycReview(ctx context.Context, request DecideKycReviewRequestObject) (DecideKycReviewResponseObject, error)
	// GetStaffDocumentContent Download an account's document (staff only)
	// (GET /v1/accounts/staff/tenants/{id}/documents/{docId}/content)
	GetStaffDocumentContent(ctx context.Context, request GetStaffDocumentContentRequestObject) (GetStaffDocumentContentResponseObject, error)
	// CreateStaffReseller Make an account a reseller (staff only)
	// (POST /v1/accounts/staff/tenants/{id}/reseller)
	CreateStaffReseller(ctx context.Context, request CreateStaffResellerRequestObject) (CreateStaffResellerResponseObject, error)
	// CreateStaffTierChange Change an account's tier (staff only)
	// (POST /v1/accounts/staff/tenants/{id}/tier-changes)
	CreateStaffTierChange(ctx context.Context, request CreateStaffTierChangeRequestObject) (CreateStaffTierChangeResponseObject, error)
	// CreateTenant Create a client account
	// (POST /v1/accounts/tenants)
	CreateTenant(ctx context.Context, request CreateTenantRequestObject) (CreateTenantResponseObject, error)
	// GetTenant Show a client account the caller belongs to
	// (GET /v1/accounts/tenants/{id})
	GetTenant(ctx context.Context, request GetTenantRequestObject) (GetTenantResponseObject, error)
	// GetBusinessProfile The account's business profile and its owners
	// (GET /v1/accounts/tenants/{id}/business-profile)
	GetBusinessProfile(ctx context.Context, request GetBusinessProfileRequestObject) (GetBusinessProfileResponseObject, error)
	// SetBusinessProfile Enter or change the business profile
	// (PUT /v1/accounts/tenants/{id}/business-profile)
	SetBusinessProfile(ctx context.Context, request SetBusinessProfileRequestObject) (SetBusinessProfileResponseObject, error)
	// AddBusinessOwner Add a director, owner or signatory
	// (POST /v1/accounts/tenants/{id}/business-profile/owners)
	AddBusinessOwner(ctx context.Context, request AddBusinessOwnerRequestObject) (AddBusinessOwnerResponseObject, error)
	// RemoveBusinessOwner Remove a director, owner or signatory
	// (DELETE /v1/accounts/tenants/{id}/business-profile/owners/{ownerId})
	RemoveBusinessOwner(ctx context.Context, request RemoveBusinessOwnerRequestObject) (RemoveBusinessOwnerResponseObject, error)
	// ListDocuments List an account's documents
	// (GET /v1/accounts/tenants/{id}/documents)
	ListDocuments(ctx context.Context, request ListDocumentsRequestObject) (ListDocumentsResponseObject, error)
	// UploadDocument Upload a document
	// (POST /v1/accounts/tenants/{id}/documents)
	UploadDocument(ctx context.Context, request UploadDocumentRequestObject) (UploadDocumentResponseObject, error)
	// GetDocumentContent Download a document
	// (GET /v1/accounts/tenants/{id}/documents/{docId}/content)
	GetDocumentContent(ctx context.Context, request GetDocumentContentRequestObject) (GetDocumentContentResponseObject, error)
	// CreateInvitation Invite someone to an account by email
	// (POST /v1/accounts/tenants/{id}/invitations)
	CreateInvitation(ctx context.Context, request CreateInvitationRequestObject) (CreateInvitationResponseObject, error)
	// SubmitKyb Submit the business for verification
	// (POST /v1/accounts/tenants/{id}/kyb-submissions)
	SubmitKyb(ctx context.Context, request SubmitKybRequestObject) (SubmitKybResponseObject, error)
	// ListKycChecks List an account's KYC checks
	// (GET /v1/accounts/tenants/{id}/kyc-checks)
	ListKycChecks(ctx context.Context, request ListKycChecksRequestObject) (ListKycChecksResponseObject, error)
	// CreateKycCheck Start a KYC check
	// (POST /v1/accounts/tenants/{id}/kyc-checks)
	CreateKycCheck(ctx context.Context, request CreateKycCheckRequestObject) (CreateKycCheckResponseObject, error)
	// ListMembers List an account's members
	// (GET /v1/accounts/tenants/{id}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// RemoveMember Remove a member, or leave an account
	// (DELETE /v1/accounts/tenants/{id}/members/{userId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// UpdateMember Change a member's role
	// (PATCH /v1/accounts/tenants/{id}/members/{userId})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)
	// ListServices The service catalogue for an account
	// (GET /v1/accounts/tenants/{id}/services)
	ListServices(ctx context.Context, request ListServicesRequestObject) (ListServicesResponseObject, error)
	// DeselectService Remove a selected service
	// (DELETE /v1/accounts/tenants/{id}/services/{code})
	DeselectService(ctx context.Context, request DeselectServiceRequestObject) (DeselectServiceResponseObject, error)
	// SelectService Select a service
	// (PUT /v1/accounts/tenants/{id}/services/{code})
	SelectService(ctx context.Context, request SelectServiceRequestObject) (SelectServiceResponseObject, error)
	// ListSubAccounts List a reseller's sub-accounts
	// (GET /v1/accounts/tenants/{id}/sub-accounts)
	ListSubAccounts(ctx context.Context, request ListSubAccountsRequestObject) (ListSubAccountsResponseObject, error)
	// CreateSubAccount Create a sub-account under a reseller
	// (POST /v1/accounts/tenants/{id}/sub-accounts)
	CreateSubAccount(ctx context.Context, request CreateSubAccountRequestObject) (CreateSubAccountResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

